mapper.select:
SELECT ba.bank_account_id, ba.bp_id, ba.bank_account_num, ba.bank_account_name, ba.currency, ba.bank_full_name, ba.bank_branch_name, ba.country, ba.REMARKS, hbm.BP_NAME, hbm.BP_CODE, (select fp.description from fnd_province fp where fp.province = ba.province) province, (select fc.description from fnd_city fc where fc.city = ba.city) city, (select fd.description from fnd_district fd where fd.district = ba.district) district, ba.debt_bank_id, (select hdb.BANK_NAME from hls_debt_deduction_bank hdb where hdb.BANK_ID = ba.debt_bank_id) debt_bank_name, (select hdb.BANK_CODE from hls_debt_deduction_bank hdb where hdb.BANK_ID = ba.debt_bank_id) debt_bank_code, ba.debt_flag, ba.bank_account_type FROM hls_bp_master_bank_account ba left join HLS_BP_MASTER hbm ON ba.BP_ID = hbm.BP_ID where 1=1
and ba.bp_id =#{bpId}
and ba.bank_account_id =#{bankAccountId}
and ba.bank_account_num LIKE concat(concat('%',#{bankAccountNum}),'%')
/*--添加按照账户名称去模糊查询 by tengfei*/
and ba.bank_account_name like concat(concat('%',#{bankAccountName}),'%')
and hbm.bp_name like concat(concat('%',#{bpName}),'%')
and ba.bank_full_name LIKE concat(concat('%',#{bankFullName}),'%')

mapper.update:
update hls_bp_master_bank_account
set debt_bank_id = null
where bank_account_id = #{bankAccountId}

mapper.select:
select t1.*, hbm.BP_NAME, hbm.BP_CODE from hls_bp_master_bank_account t1 left join HLS_BP_MASTER hbm ON t1.BP_ID = hbm.BP_ID
1=1
and t1.bank_account_num =#{bankAccountNum}
