SELECT ba.bank_account_id, ba.bp_id, ba.bank_account_num, ba.bank_account_name, ba.currency, ba.bank_full_name, ba.bank_branch_name, ba.country, ba.REMARKS, hbm.BP_NAME, hbm.BP_CODE, (select fp.description from fnd_province fp where fp.province = ba.province) province, (select fc.description from fnd_city fc where fc.city = ba.city) city, (select fd.description from fnd_district fd where fd.district = ba.district) district, ba.debt_bank_id, (select hdb.BANK_NAME from hls_debt_deduction_bank hdb where hdb.BANK_ID = ba.debt_bank_id) debt_bank_name, (select hdb.BANK_CODE from hls_debt_deduction_bank hdb where hdb.BANK_ID = ba.debt_bank_id) debt_bank_code, ba.debt_flag, ba.bank_account_type FROM hls_bp_master_bank_account ba join HLS_BP_MASTER hbm ON ba.BP_ID = hbm.BP_ID
left join FCT_PROJECT_BP fpb ON hbm.BP_ID = fpb.BP_ID
where 1=1
and fpb.BP_ROLE_TYPE = 'SELLER' and fpb.project_Id = #{projectId}
and ba.bp_id =#{bpId}
and ba.bank_account_id =#{bankAccountId}
and ba.bank_account_num LIKE concat(concat('%',#{bankAccountNum}),'%')
/*--添加按照账户名称去模糊查询 by tengfei*/
and ba.bank_account_name like concat(concat('%',#{bankAccountName}),'%')
and hbm.bp_name like concat(concat('%',#{bpName}),'%')
and ba.bank_full_name LIKE concat(concat('%',#{bankFullName}),'%')

SELECT ba.bank_account_id, ba.bp_id, ba.bank_account_num, ba.bank_account_name, ba.currency, ba.bank_full_name, ba.bank_branch_name, ba.country, ba.REMARKS, hbm.BP_NAME, hbm.BP_CODE, (select fp.description from fnd_province fp where fp.province = ba.province) province, (select fc.description from fnd_city fc where fc.city = ba.city) city, (select fd.description from fnd_district fd where fd.district = ba.district) district, ba.debt_bank_id, (select hdb.BANK_NAME from hls_debt_deduction_bank hdb where hdb.BANK_ID = ba.debt_bank_id) debt_bank_name, (select hdb.BANK_CODE from hls_debt_deduction_bank hdb where hdb.BANK_ID = ba.debt_bank_id) debt_bank_code, ba.debt_flag, ba.bank_account_type FROM hls_bp_master_bank_account ba left join HLS_BP_MASTER hbm ON ba.BP_ID = hbm.BP_ID
left join PRJ_PROJECT_BP ppb ON hbm.BP_ID = ppb.BP_ID
where 1=1 and ppb.bp_role_type='CLIENT'
and ppb.project_Id = #{projectId}
and ba.bp_id =#{bpId}
and ba.bank_account_id =#{bankAccountId}
and ba.bank_account_num LIKE concat(concat('%',#{bankAccountNum}),'%')
and ba.bank_account_name like concat(concat('%',#{bankAccountName}),'%')
and hbm.bp_name like concat(concat('%',#{bpName}),'%')
and ba.bank_full_name LIKE concat(concat('%',#{bankFullName}),'%')

SELECT ba.*, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'BANK_TYPE_BP' and sc.code_value = ba.BANK_ACCOUNT_TYPE) BANK_ACCOUNT_TYPE_N, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'BANK_SIGN_TYPE' and sc.code_value = ba.BANK_SIGN_TYPE) BANK_SIGN_TYPE_N FROM hls_bp_master_bank_account ba
and ba.bp_id =#{bpId}
order by ba.bank_account_id desc

select * from hls_bp_master_bank_account t

    t.enabled_flag = 'Y'

        and t.bp_id  = #{bpId}



        and t.bank_account_code like #{bankAccountCode}



        and t.bank_account_num like #{bankAccountNum}



        and t.bank_account_name like #{bankAccountName}



        and t.bank_full_name like #{bankFullName}



        and t.bank_branch_name like #{bankBranchName}
